files.app.js:
'use strict';
const tbody = document.querySelector('#orders tbody');
function countRows() { document.getElementById('row-count').textContent = tbody.rows.length + ' Positionen'; }
document.getElementById('row-add').addEventListener('click', function () { const row = tbody.insertRow(-1); row.insertCell(0).textContent = 'Bleistift'; row.insertCell(1).textContent = '3'; countRows(); });
document.getElementById('row-remove').addEventListener('click', function () { if (tbody.rows.length) tbody.deleteRow(-1); countRows(); });
document.getElementById('note-add').addEventListener('click', function () { const fragment = document.getElementById('note-template').content.cloneNode(true); fragment.querySelector('.note-text').textContent = 'Aus dem Template eingefügt.'; document.getElementById('notes').appendChild(fragment); });
document.getElementById('note-move').addEventListener('click', function () { const list = document.getElementById('notes'); if (list.children.length > 1) list.appendChild(list.firstElementChild); });

