files.app.js:
'use strict';
const form = document.getElementById('booking');
form.addEventListener('submit', function (event) { event.preventDefault(); const data = new FormData(form); document.getElementById('form-status').textContent = data.get('name') + ' | ' + data.get('email') + ' | ' + data.get('guests') + ' Personen'; });
form.addEventListener('reset', function () { document.getElementById('form-status').textContent = 'Zurückgesetzt.'; });
document.getElementById('form-range').addEventListener('input', function (event) { document.getElementById('range-value').textContent = event.target.value; document.getElementById('form-bar').style.width = event.target.value + '%'; });
document.getElementById('form-color').addEventListener('input', function (event) { document.getElementById('form-bar').style.backgroundColor = event.target.value; });
document.getElementById('form-check').addEventListener('change', function (event) { document.getElementById('form-bar').classList.toggle('outlined', event.target.checked); });

