return [==[
'use strict';
document.getElementById('layer-check').addEventListener('change', function (event) { document.getElementById('layer-wrap').classList.toggle('reverted', event.target.checked); });
document.getElementById('variable-check').addEventListener('change', function (event) { document.getElementById('variable-sample').classList.toggle('valid', event.target.checked); });
