'use strict';
document.getElementById('container-width').addEventListener('input', function (event) { document.getElementById('container-value').textContent = event.target.value; document.getElementById('query-container').style.width = event.target.value + 'px'; });
document.getElementById('flex-check').addEventListener('change', function (event) { document.getElementById('flex-demo').classList.toggle('wrap', event.target.checked); });

