table { border-collapse: collapse; width: 100%; }
th, td { border: 1px solid #bdc9d4; padding: 9px; text-align: left; }
th { background: #e8eef7; }
.sample { padding: 16px; border: 2px solid #afbbc8; border-radius: 6px; background: white; }
.swatch { color: white; border-radius: 6px; padding: 24px; }
