'use strict';
let loopRunning = false;
document.getElementById('loop-start').addEventListener('click', function () { if (loopRunning) return; loopRunning = true; const list = document.getElementById('loop-results'); list.textContent = ''; function write(value) { const item = document.createElement('li'); item.textContent = value; list.appendChild(item); } write('1. synchron'); Promise.resolve().then(function () { write('2. Promise'); }); setTimeout(function () { write('3. Timer'); loopRunning = false; }, 0); });
const dialog = document.getElementById('request-dialog');
document.getElementById('dialog-modal').addEventListener('click', function () { if (dialog.open) dialog.close(); dialog.showModal(); });
document.getElementById('dialog-normal').addEventListener('click', function () { if (dialog.open) dialog.close(); dialog.show(); });
document.getElementById('dialog-close').addEventListener('click', function () { dialog.close(); });
const note = document.getElementById('saved-note');
try { const saved = localStorage.getItem('comparison.note.v1'); if (saved !== null) { note.value = saved; document.getElementById('storage-status').textContent = 'Gespeicherte Notiz geladen.'; } } catch (error) { document.getElementById('storage-status').textContent = 'Speicherung derzeit nicht verfügbar.'; }
document.getElementById('note-save').addEventListener('click', function () { try { localStorage.setItem('comparison.note.v1', note.value); document.getElementById('storage-status').textContent = 'Notiz gespeichert.'; } catch (error) { document.getElementById('storage-status').textContent = 'Speicherung derzeit nicht verfügbar.'; } });
document.getElementById('note-clear').addEventListener('click', function () { try { localStorage.removeItem('comparison.note.v1'); note.value = ''; document.getElementById('storage-status').textContent = 'Notiz gelöscht.'; } catch (error) { document.getElementById('storage-status').textContent = 'Speicherung derzeit nicht verfügbar.'; } });

const idleStatus = document.getElementById('idle-status');
const idleSupported = typeof window.requestIdleCallback === 'function' && typeof window.cancelIdleCallback === 'function';
let idleHandle = null;
function cancelPendingIdle() {
  if (idleHandle === null) return false;
  window.cancelIdleCallback(idleHandle);
  idleHandle = null;
  return true;
}
if (!idleSupported) {
  idleStatus.textContent = 'Dieser Browser stellt requestIdleCallback und cancelIdleCallback nicht bereit.';
  for (const id of ['idle-start', 'idle-cancel', 'idle-cancel-now']) document.getElementById(id).disabled = true;
}
document.getElementById('idle-start').addEventListener('click', function () {
  if (!idleSupported) return;
  cancelPendingIdle();
  idleStatus.textContent = 'Geplant. Der Callback wartet auf eine freie Pause oder seine Wartefrist.';
  idleHandle = window.requestIdleCallback(function (deadline) {
