/* Each route contains only its own examples. No external resources. */
:root { color-scheme: light; --ink: #223447; --muted: #617283; --line: #d4dce1; --blue: #315cc4; }
* { box-sizing: border-box; }
body { margin: 0; background: #f4f6f8; color: var(--ink); font: 16px/1.55 Arial, sans-serif; }
h1, h2, h3, p { margin-top: 0; }
h1 { font-size: clamp(28px, 4vw, 44px); line-height: 1.15; margin-bottom: 18px; }
h2 { font-size: 23px; line-height: 1.25; }
h3 { font-size: 18px; }
a { color: var(--blue); }
a:hover { color: #173775; }
button, input, select, textarea { font: inherit; }
button, .button { display: inline-block; background: white; color: var(--ink); border: 1px solid #b6c4cf; border-radius: 5px; padding: 9px 13px; cursor: pointer; text-decoration: none; line-height: 1.4; }
button:hover, .button:hover { background: #e8eefb; border-color: var(--blue); }
button:disabled { opacity: .5; cursor: default; }
:focus-visible { outline: 2px solid var(--blue); outline-offset: 3px; }
input:not([type=checkbox]):not([type=radio]):not([type=range]):not([type=color]):not([type=file]), select, textarea { width: 100%; max-width: 100%; padding: 8px; border: 1px solid #b6c4cf; border-radius: 4px; background: white; color: var(--ink); }
input[type=range] { width: 100%; }
label { display: block; margin: 12px 0 6px; }
.wrap { max-width: 1000px; margin: 0 auto; padding: 0 24px; }
header { background: white; border-bottom: 1px solid var(--line); }
.header-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 72px; }
.brand { font-weight: bold; font-size: 20px; text-decoration: none; }
.hero { padding: 42px 0 24px; max-width: 760px; }
.eyebrow { font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: #965038; margin-bottom: 12px; }
.muted { color: var(--muted); }
.cards { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 22px; align-items: start; }
.card { min-width: 0; padding: 24px; background: white; border: 1px solid var(--line); border-radius: 8px; }
.card:last-child:nth-child(odd) { grid-column: 1 / -1; }
.hub .card:last-child { grid-column: auto; }
.stage { background: #edf1f7; padding: 18px; border-radius: 6px; margin: 16px 0; min-width: 0; }
.controls { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; margin: 16px 0; }
.expect { font-size: 14px; border-left: 3px solid #b6c7d9; padding-left: 12px; margin: 18px 0 0; color: var(--muted); }
.status { background: #edf2e8; padding: 12px; margin: 16px 0 0; overflow-wrap: anywhere; }
details.rules { border-top: 1px solid var(--line); margin-top: 20px; padding-top: 12px; }
summary { cursor: pointer; }
pre { font: 13px/1.5 Consolas, monospace; white-space: pre-wrap; overflow-wrap: anywhere; margin-bottom: 0; }
code { font-family: Consolas, monospace; }
.nav-bottom { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 16px; padding: 30px 0; }
footer { border-top: 1px solid var(--line); padding: 22px 0 34px; font-size: 13px; color: var(--muted); }
table { border-collapse: collapse; width: 100%; }
th, td { border: 1px solid #bdc9d4; padding: 9px; text-align: left; }
th { background: #e8eef7; }
.sample { padding: 16px; border: 2px solid #afbbc8; border-radius: 6px; background: white; }
.swatch { color: white; border-radius: 6px; padding: 24px; }
.chips { display: flex; flex-wrap: wrap; gap: 10px; }
.chips span { padding: 10px; background: #dce6ef; border-radius: 4px; }
@media (max-width: 700px) { .wrap { padding: 0 16px; } .cards { grid-template-columns: minmax(0, 1fr); } .card { padding: 18px; } .hero { padding-top: 28px; } .header-row { flex-wrap: wrap; padding-top: 14px; padding-bottom: 14px; } }

dialog { max-width: calc(100% - 32px); width: 380px; padding: 24px; border: 1px solid #afbbc8; border-radius: 10px; color: #223447; } dialog::backdrop { background: #22344788; } [popover] { max-width: calc(100% - 32px); padding: 24px; border: 1px solid #afbbc8; border-radius: 8px; }

