'use strict';
const root = document.documentElement;
const owner = document.getElementById('owner');
const alpha = document.getElementById('alpha');
const opacity = document.getElementById('opacity');
function paint() {
  root.classList.toggle('root-paint', owner.value === 'root');
  root.classList.toggle('no-paint', owner.value === 'none');
  root.style.setProperty('--canvas-alpha', String(Number(alpha.value) / 100));
  document.getElementById('alpha-value').textContent = alpha.value + '%';
}
owner.addEventListener('change', paint);
alpha.addEventListener('input', paint);
document.getElementById('dark').addEventListener('change', function (event) {
  root.style.colorScheme = event.target.checked ? 'dark' : 'light';
});
opacity.addEventListener('input', function () {
  root.style.opacity = String(Number(opacity.value) / 100);
  document.getElementById('opacity-value').textContent = opacity.value + '%';
});
document.getElementById('switch').addEventListener('click', function () {
  owner.value = owner.value === 'root' ? 'body' : 'root';
  paint();
});
document.getElementById('hover').addEventListener('change', function (event) {
  document.body.classList.toggle('hover-paint', event.target.checked);
});
document.getElementById('grow').addEventListener('click', function (event) {
  const existing = document.getElementById('growth');
  if (existing) {
    existing.remove();
  } else {
    const extra = document.createElement('div');
    extra.id = 'growth';
    extra.className = 'growth';
    extra.textContent = '900 Pixel zusätzlicher Inhalt. Der Seitenhintergrund reicht auch hinter diesen Bereich.';
    document.getElementById('growth-target').appendChild(extra);
  }
  event.currentTarget.setAttribute('aria-expanded', String(!existing));
  event.currentTarget.textContent = existing ? 'Langen Inhalt einfügen' : 'Zusätzlichen Inhalt entfernen';
  document.getElementById('growth-status').textContent = existing ? 'Kein zusätzlicher Inhalt.' : 'Zusätzlicher Inhalt ist eingefügt.';
});

