"use strict";

// Native controls own values, picking, stepping, validation and reset.
// This script only displays their actual results and prevents network submission.
const forms = Array.from(document.querySelectorAll("form[data-example]"));
const previews = new Map();

function fileRecord(file) {
  return { name: file.name, size: file.size, type: file.type || "nicht gemeldet", lastModified: file.lastModified };
}

function formRecord(form, submitter) {
  return Array.from(new FormData(form, submitter || undefined), ([name, value]) => ({
    name,
    value: value instanceof File ? fileRecord(value) : value
  }));
}

function validationMessage(field) {
  const state = field.validity;
  if (state.badInput) return "Die Eingabe ist noch unvollständig oder nicht lesbar.";
  if (state.valueMissing) return "Pflichtfeld: Bitte einen Wert wählen.";
  if (state.rangeUnderflow) return "Der Wert liegt vor der erlaubten Untergrenze.";
  if (state.rangeOverflow) return "Der Wert liegt nach der erlaubten Obergrenze.";
  if (state.stepMismatch) return "Der Wert liegt zwischen den erlaubten Schritten.";
  if (!state.valid) return field.validationMessage;
  return field.value ? "Zulässiger Wert." : "Leer ist hier erlaubt.";
}

function releasePreviews(form) {
  for (const url of previews.get(form) || []) URL.revokeObjectURL(url);
  previews.delete(form);
}

function refreshFilePreview(form) {
  releasePreviews(form);
  const area = form.querySelector("[data-preview]");
  area.replaceChildren();
  const urls = [];
  const files = Array.from(form.querySelectorAll('input[type="file"]')).flatMap(field => Array.from(field.files));
  for (const file of files.filter(file => file.type.startsWith("image/")).slice(0, 3)) {
    const url = URL.createObjectURL(file);
    urls.push(url);
    const image = document.createElement("img");
    image.src = url;
    image.alt = file.name;
    area.append(image);
  }
  previews.set(form, urls);
  area.hidden = urls.length === 0;
