function refresh(form) {
  const kind = form.dataset.example;
  const output = form.querySelector("[data-value]");
  const state = form.querySelector("[data-validity]");
  if (kind === "image") return;
  const primary = form.querySelector(".sample-field");
  if (kind === "file") {
    const fields = Array.from(form.querySelectorAll('input[type="file"]'));
    const files = fields.flatMap(field => Array.from(field.files));
    output.textContent = files.length ? files.map(file => {
      const size = file.size < 1024 ? `${file.size} B` : `${(file.size / 1024).toFixed(1)} KiB`;
      return `${file.name}\n${size} · ${file.type || "Typ nicht gemeldet"}`;
    }).join("\n\n") : "Keine Datei ausgewählt.";
    state.textContent = files.length ? `${files.length} Datei${files.length === 1 ? "" : "en"} ausgewählt.` : "Dateiauswahl ist freiwillig.";
    state.dataset.state = "valid";
    refreshFilePreview(form);
    return;
  }
  output.textContent = primary.value || "(leer)";
  if (primary.type !== kind) {
    state.textContent = `Dieser Browser behandelt ${kind} als ${primary.type}.`;
    state.dataset.state = "unsupported";
  } else {
