for (const form of forms) {
  const submission = form.querySelector("[data-submission]");
  const initialSubmission = submission.textContent;
  const dataOutput = form.querySelector("[data-form-data]");
  const initialData = dataOutput.textContent;
  const primary = form.querySelector(".sample-field");
  form.addEventListener("input", () => refresh(form));
  form.addEventListener("change", () => refresh(form));
  form.addEventListener("invalid", () => {
    refresh(form);
    submission.textContent = "Noch nicht bestätigt: Bitte die markierte Eingabe korrigieren.";
  }, true);
  form.addEventListener("submit", event => {
    event.preventDefault();
    const record = formRecord(form, event.submitter);
    dataOutput.textContent = JSON.stringify(record, null, 2);
    submission.textContent = "Lokal bestätigt. Die tatsächlichen Formulardaten stehen unter dem Feld.";
    if (form.dataset.example === "image") {
      const values = new Map(record.map(entry => [entry.name, entry.value]));
      form.querySelector("[data-value]").textContent = `x: ${values.get("anfrage.x")} px · y: ${values.get("anfrage.y")} px`;
      form.querySelector("[data-validity]").textContent = "Bildbutton hat das Formular abgesendet.";
    }
  });
  form.addEventListener("reset", () => {
    // The reset event precedes restoration. A microtask checkpoint can also
    // precede the native default action; read values in the following task.
    setTimeout(() => {
      refresh(form);
      submission.textContent = initialSubmission;
      dataOutput.textContent = initialData;
      if (form.dataset.example === "image") {
        form.querySelector("[data-value]").textContent = "Noch keine Anfrage.";
        form.querySelector("[data-validity]").textContent = "";
      }
    }, 0);
  });
  for (const button of form.querySelectorAll("[data-step]")) {
    button.addEventListener("click", () => {
      try {
        if (Number(button.dataset.step) > 0) primary.stepUp();
        else primary.stepDown();
        refresh(form);
      } catch (error) {
        submission.textContent = `Dieser Browser kann den Wert hier nicht schrittweise ändern: ${error.name}.`;
      }
    });
  }
  const clear = form.querySelector("[data-clear]");
  if (clear) clear.addEventListener("click", () => { primary.value = ""; refresh(form); });
  refresh(form);
}

window.addEventListener("pagehide", () => { for (const form of previews.keys()) releasePreviews(form); });
window.addEventListener("pageshow", event => { if (event.persisted) for (const form of forms) refresh(form); });

files.styles.css:
:root { color-scheme: light; --paper: #f3f4ef; --ink: #203c35; --muted: #65726b; --line: #dce2d8; --accent: #b84d36; }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 24px; }
body { margin: 0; background: var(--paper); color: var(--ink); font: 16px/1.6 Arial, sans-serif; }
a { color: inherit; }
button, input { font: inherit; }
button { cursor: pointer; }
input, button, a, summary { -webkit-tap-highlight-color: transparent; }
button:focus-visible, a:focus-visible, summary:focus-visible, input:focus-visible { outline: 2px solid #161c19; outline-offset: 3px; }
button:disabled { cursor: default; }
[hidden] { display: none !important; }
.container { width: calc(100% - 64px); max-width: 1120px; margin: 0 auto; }
.skip-link { position: absolute; top: -100px; left: 24px; padding: 10px 16px; background: var(--ink); color: white; z-index: 2; }
.skip-link:focus { top: 14px; }
.site-header { min-height: 90px; display: flex; gap: 24px; justify-content: space-between; align-items: center; padding: 20px max(32px, calc((100% - 1120px) / 2)); border-bottom: 1px solid var(--line); }
.brand { font-size: 22px; font-weight: 700; letter-spacing: -1px; text-decoration: none; }
.brand > span { color: var(--accent); }
.header-note, .back-link { font-size: 12px; color: var(--muted); }
.back-link { text-decoration: none; border-bottom: 1px solid #8c9b8f; }
.hero { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(0, .7fr); gap: 72px; align-items: end; padding: 60px 0 36px; }
.eyebrow { display: block; margin: 0 0 14px; color: var(--accent); font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; }
h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 24px; font-size: 60px; line-height: 1.04; letter-spacing: -2.5px; }
h1 em { color: var(--accent); font-style: normal; }
.hero-description { max-width: 590px; color: var(--muted); font-size: 17px; margin-bottom: 0; }
.intro-note { padding: 24px; display: flex; gap: 20px; align-items: start; border-left: 2px solid #acb99d; background: #e8ede3; }
.note-number { font-size: 56px; line-height: 1; font-weight: 700; letter-spacing: -3px; }
.intro-note strong { font-size: 14px; }
.intro-note p { color: var(--muted); font-size: 13px; margin: 8px 0 0; }
.type-nav { display: flex; flex-wrap: wrap; gap: 8px; padding: 8px 0 24px; }
.type-nav a { padding: 8px 15px; border: 1px solid #cbd5c5; border-radius: 30px; text-decoration: none; font-size: 13px; background: #fffefa; }
.type-nav a:hover { background: #e5ebdf; }
.reference-note { display: flex; gap: 12px; padding: 17px 20px; margin-bottom: 28px; border: 1px solid #d5decf; background: #e9eee4; border-radius: 6px; }
.reference-note p { margin: 0; font-size: 13px; }
.status-dot { width: 8px; height: 8px; flex-shrink: 0; margin-top: 7px; border-radius: 50%; background: #8a9b74; }
.notice { border: 1px solid #d8ae95; background: #fff0df; padding: 16px; }
.examples-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 22px; align-items: start; }
.example-card { padding: 30px; border: 1px solid #d1dacf; border-radius: 10px; background: #fffefa; min-width: 0; scroll-margin-top: 24px; }
.card-heading { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 20px; }
.card-heading .eyebrow { margin: 0; }
code { font: 12px/1.6 Consolas, monospace; }
.card-heading code { padding: 3px 8px; color: #627063; background: #edf1e8; border-radius: 4px; }
h2 { margin-bottom: 12px; font-size: 26px; line-height: 1.2; letter-spacing: -.7px; }
.description { color: var(--muted); font-size: 14px; min-height: 68px; margin-bottom: 24px; }
label { display: block; font-size: 13px; font-weight: 700; margin-bottom: 7px; }
input:not([type="hidden"]):not([type="image"]) { display: block; width: 100%; min-width: 0; min-height: 46px; border: 1px solid #a8b6a4; border-radius: 4px; background: white; color: #172f28; padding: 10px 12px; }
input[type="file"] { font-size: 12px; padding: 10px 8px !important; }
input[type="file"]::file-selector-button { font: inherit; padding: 5px 8px; margin-right: 10px; }
input:disabled { background: #eef0eb !important; color: #80867d !important; }
input[readonly] { background: #f2f5ee !important; }
.field-hint { font-size: 12px; color: var(--muted); margin: 8px 0 16px; }
.step-actions { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 20px; }
.step-actions button { padding: 5px 9px; background: #fffefa; color: #53664f; border: 1px solid #d2dbcc; border-radius: 4px; font-size: 12px; }
.step-actions button:hover { background: #edf1e8; }
.live-result { background: #eff3ea; padding: 14px 16px; border-radius: 5px; border-left: 2px solid #a6b691; margin-bottom: 20px; }
.live-result > span { display: block; font-size: 10px; letter-spacing: 1px; text-transform: uppercase; color: #65775d; margin-bottom: 5px; }
output { display: block; font: 15px/1.6 Consolas, monospace; white-space: pre-wrap; overflow-wrap: anywhere; }
.live-result p { font-size: 12px; margin: 6px 0 0; color: #54714b; }
.live-result p[data-state="invalid"] { color: #a23922; }
.live-result p[data-state="unsupported"] { color: #9a5925; }
.form-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.button { border: 1px solid var(--ink); border-radius: 4px; padding: 9px 15px; background: var(--ink); color: white; font-size: 13px; }
.button:hover { background: #34564b; }
.button.secondary { background: #fffefa; color: var(--ink); border-color: #b3c0ad; }
.button.secondary:hover { background: #edf1e8; }
.submission { margin: 12px 0 18px; font-size: 12px; color: var(--muted); min-height: 20px; }
details { border-top: 1px solid var(--line); padding-top: 14px; }
summary { font-size: 12px; color: #4d6452; cursor: pointer; }
pre { white-space: pre-wrap; overflow-wrap: anywhere; font: 12px/1.7 Consolas, monospace; padding: 13px; background: #f1f2ed; border: 1px solid #e0e4d9; border-radius: 4px; }
.form-data { color: #596b53; }
.state-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.state-fields label { font-size: 11px; }
.file-preview { display: flex; gap: 8px; flex-wrap: wrap; margin: 16px 0; }
.file-preview img { width: 82px; height: 65px; object-fit: cover; border: 1px solid var(--line); border-radius: 5px; }
.wide-card { grid-column: 1 / -1; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 40px; }
.wide-card .description { min-height: 0; }
.image-submit { display: block; width: 100%; max-width: 480px; height: auto; border-radius: 8px; border: 1px solid #c9d2bd; margin: 10px 0 18px; cursor: pointer; }
.image-submit:hover { border-color: #738866; }
.try-note { margin: 38px 0 48px; padding: 30px; background: #e9eee4; border: 1px solid #d6dfce; border-radius: 8px; }
.try-note h2 { font-size: 27px; }
.try-note ol { padding-left: 22px; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px 40px; margin: 22px 0; }
.try-note li { padding-left: 3px; font-size: 13px; color: #586b50; }
.try-note .field-hint { margin-bottom: 0; }
.site-footer { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 18px; padding-bottom: 30px; }
.site-footer .brand { font-size: 18px; }
.site-footer p, .site-footer > a { margin: 0; font-size: 11px; color: var(--muted); }
@media (max-width: 950px) { .hero { gap: 24px; grid-template-columns: minmax(0, 1fr) minmax(0, .65fr); } h1 { font-size: 50px; } .example-card { padding: 24px; } .card-heading { align-items: start; } }
@media (max-width: 700px) {
  .container { width: calc(100% - 32px); } .site-header { padding: 18px 16px; min-height: 76px; gap: 12px; }
  .brand { font-size: 20px; } .header-note { display: none; } .back-link { font-size: 11px; }
  .hero { grid-template-columns: minmax(0, 1fr); padding-top: 35px; gap: 24px; } h1 { font-size: 48px; }
  .intro-note { padding: 18px; } .note-number { font-size: 44px; } .hero-description { font-size: 15px; }
  .examples-grid, .wide-card { grid-template-columns: minmax(0, 1fr); } .wide-card { gap: 12px; }
  .example-card { padding: 23px; } .description { min-height: 0; } .try-note { padding: 23px; }
  .try-note ol { grid-template-columns: minmax(0, 1fr); gap: 12px; } .state-fields { grid-template-columns: minmax(0, 1fr); }
}
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }

