"use strict";

// Native controls own values, picking, stepping, validation and reset.
// This script only displays their actual results and prevents network submission.
const forms = Array.from(document.querySelectorAll("form[data-example]"));
const previews = new Map();

function fileRecord(file) {
  return { name: file.name, size: file.size, type: file.type || "nicht gemeldet", lastModified: file.lastModified };
}

function formRecord(form, submitter) {
  return Array.from(new FormData(form, submitter || undefined), ([name, value]) => ({
    name,
    value: value instanceof File ? fileRecord(value) : value
  }));
}

function validationMessage(field) {
  const state = field.validity;
  if (state.badInput) return "Die Eingabe ist noch unvollständig oder nicht lesbar.";
  if (state.valueMissing) return "Pflichtfeld: Bitte einen Wert wählen.";
  if (state.rangeUnderflow) return "Der Wert liegt vor der erlaubten Untergrenze.";
  if (state.rangeOverflow) return "Der Wert liegt nach der erlaubten Obergrenze.";
  if (state.stepMismatch) return "Der Wert liegt zwischen den erlaubten Schritten.";
  if (!state.valid) return field.validationMessage;
  return field.value ? "Zulässiger Wert." : "Leer ist hier erlaubt.";
}

function releasePreviews(form) {
  for (const url of previews.get(form) || []) URL.revokeObjectURL(url);
  previews.delete(form);
}

function refreshFilePreview(form) {
  releasePreviews(form);
  const area = form.querySelector("[data-preview]");
  area.replaceChildren();
  const urls = [];
  const files = Array.from(form.querySelectorAll('input[type="file"]')).flatMap(field => Array.from(field.files));
  for (const file of files.filter(file => file.type.startsWith("image/")).slice(0, 3)) {
    const url = URL.createObjectURL(file);
    urls.push(url);
    const image = document.createElement("img");
    image.src = url;
    image.alt = file.name;
    area.append(image);
  }
  previews.set(form, urls);
  area.hidden = urls.length === 0;
}

function refresh(form) {
  const kind = form.dataset.example;
  const output = form.querySelector("[data-value]");
  const state = form.querySelector("[data-validity]");
  if (kind === "image") return;
  const primary = form.querySelector(".sample-field");
  if (kind === "file") {
    const fields = Array.from(form.querySelectorAll('input[type="file"]'));
    const files = fields.flatMap(field => Array.from(field.files));
    output.textContent = files.length ? files.map(file => {
      const size = file.size < 1024 ? `${file.size} B` : `${(file.size / 1024).toFixed(1)} KiB`;
      return `${file.name}\n${size} · ${file.type || "Typ nicht gemeldet"}`;
    }).join("\n\n") : "Keine Datei ausgewählt.";
    state.textContent = files.length ? `${files.length} Datei${files.length === 1 ? "" : "en"} ausgewählt.` : "Dateiauswahl ist freiwillig.";
    state.dataset.state = "valid";
    refreshFilePreview(form);
    return;
  }
  output.textContent = primary.value || "(leer)";
  if (primary.type !== kind) {
    state.textContent = `Dieser Browser behandelt ${kind} als ${primary.type}.`;
    state.dataset.state = "unsupported";
  } else {
    // Include secondary fields such as the seconds example in the form status.
    const invalid = Array.from(form.elements).find(field => field.willValidate && !field.validity.valid);
    state.textContent = validationMessage(invalid || primary);
    state.dataset.state = invalid ? "invalid" : "valid";
  }
}

for (const form of forms) {
  const submission = form.querySelector("[data-submission]");
  const initialSubmission = submission.textContent;
  const dataOutput = form.querySelector("[data-form-data]");
  const initialData = dataOutput.textContent;
  const primary = form.querySelector(".sample-field");
  form.addEventListener("input", () => refresh(form));
  form.addEventListener("change", () => refresh(form));
  form.addEventListener("invalid", () => {
    refresh(form);
    submission.textContent = "Noch nicht bestätigt: Bitte die markierte Eingabe korrigieren.";
  }, true);
  form.addEventListener("submit", event => {
    event.preventDefault();
    const record = formRecord(form, event.submitter);
    dataOutput.textContent = JSON.stringify(record, null, 2);
    submission.textContent = "Lokal bestätigt. Die tatsächlichen Formulardaten stehen unter dem Feld.";
    if (form.dataset.example === "image") {
      const values = new Map(record.map(entry => [entry.name, entry.value]));
      form.querySelector("[data-value]").textContent = `x: ${values.get("anfrage.x")} px · y: ${values.get("anfrage.y")} px`;
      form.querySelector("[data-validity]").textContent = "Bildbutton hat das Formular abgesendet.";
