'use strict';
(() => {
  const $ = id => document.getElementById(id);
  const log = $('activity-log');
  let stream = null;
  let mediaGeneration = 0;
  let mediaPending = false;
  let popup = null;
  let disposed = false;
  let motionX = 0;
  let motionY = 0;
  const mediaButtons = Array.from(document.querySelectorAll('[data-media]'));
  const mediaAvailable = typeof navigator.mediaDevices?.getUserMedia === 'function';

  function report(id, message, state = 'idle') {
    const target = $(id + '-result');
    target.textContent = message;
    target.dataset.state = state;
    log.querySelector('.empty-log')?.remove();
    const entry = document.createElement('li');
    const clock = document.createElement('time');
    clock.dateTime = new Date().toISOString();
    clock.textContent = new Date().toLocaleTimeString('de-DE');
    const text = document.createElement('span');
    text.textContent = message;
    entry.append(clock, text);
    log.prepend(entry);
    while (log.children.length > 12) log.lastElementChild.remove();
  }

  function badge(id, available) {
    const target = $(id + '-badge');
    target.textContent = available ? 'Im Browser verfügbar' : 'Hier nicht verfügbar';
    target.dataset.available = String(available);
  }

  function failure(error) {
    const name = error?.name || 'Fehler';
    const descriptions = {
      NotAllowedError: 'Keine Freigabe: abgelehnt, bereits gesperrt oder durch Browser/App blockiert.',
      NotFoundError: 'Kein passendes Gerät gefunden oder die Auswahl wurde abgebrochen.',
      NotReadableError: 'Das Gerät ist momentan nicht zugänglich, etwa weil es schon verwendet wird.',
      SecurityError: 'Der Browser oder die App erlaubt diese Anfrage hier nicht.',
      AbortError: 'Die Anfrage wurde abgebrochen.',
      InvalidStateError: 'Die Seite ist für diese Anfrage momentan nicht aktiv.',
      NotSupportedError: 'Diese Funktion wird in dieser Umgebung nicht unterstützt.',
      TypeError: 'Die Anfrage ist hier nicht verfügbar oder wurde vom Browser zurückgewiesen.'
    };
    return name + ': ' + (descriptions[name] || error?.message || 'Die Anfrage ist fehlgeschlagen.');
  }

  async function request(id, operation, success) {
    report(id, 'Anfrage läuft. Falls ein Dialog erscheint, entscheide dort.', 'pending');
    try {
      // Invoke immediately in the click handler to retain browser user activation.
      const value = await operation();
      if (!disposed) {
        const outcome = typeof success === 'function' ? success(value) : success;
        report(id, typeof outcome === 'string' ? outcome : outcome.message, typeof outcome === 'string' ? 'success' : outcome.state);
      }
    } catch (error) {
      if (!disposed) report(id, failure(error), 'error');
    }
  }

