    const tracks = stream?.getTracks().filter(track => track.readyState === 'live') || [];
    for (const button of mediaButtons) button.disabled = !mediaAvailable || mediaPending;
    $('media-stop').disabled = tracks.length === 0;
    const videoActive = tracks.some(track => track.kind === 'video');
    const audioActive = tracks.some(track => track.kind === 'audio');
    $('media-active').textContent = videoActive && audioActive ? 'Kamera und Mikrofon aktiv' : videoActive ? 'Kamera aktiv' : audioActive ? 'Mikrofon aktiv' : 'Kein Gerät aktiv';
    $('camera-preview').hidden = !videoActive;
    $('camera-placeholder').hidden = videoActive;
  }

  function releaseMedia() {
    mediaGeneration++;
    mediaPending = false;
    const previous = stream;
    stream = null;
    previous?.getTracks().forEach(track => track.stop());
    $('camera-preview').pause();
    $('camera-preview').srcObject = null;
    refreshMedia();
  }

  async function startMedia(kind) {
    if (mediaPending || !mediaAvailable) return;
    releaseMedia();
    const generation = ++mediaGeneration;
    mediaPending = true;
    refreshMedia();
    report('media', 'Kamera-/Mikrofonanfrage läuft. Entscheide im Browserdialog, falls er erscheint.', 'pending');
    try {
      const acquired = await navigator.mediaDevices.getUserMedia({video: kind !== 'microphone', audio: kind !== 'camera'});
      if (disposed || generation !== mediaGeneration) {
