        $('camera-preview').srcObject = acquired;
        $('camera-preview').play().catch(() => {});
      }
      report('media', 'Freigegeben. Die Geräte bleiben bis „Zugriff beenden“ aktiv; es wird nichts aufgezeichnet.', 'success');
