      if (!popup) {
        report('popup', 'Der Browser oder die App hat kein steuerbares Pop-up bereitgestellt. Möglicherweise wurde ein neuer Tab geöffnet oder das Pop-up blockiert.', 'error');
        return;
      }
      $('popup-close').disabled = false;
