  function closePopup() {
    const previous = popup;
    popup = null;
    previous?.close();
    $('popup-close').disabled = true;
  }
  $('popup-close').addEventListener('click', () => { closePopup(); report('popup', 'Das Zusatzfenster wurde geschlossen.'); });
  window.addEventListener('message', event => {
    if (event.origin === window.location.origin && event.source === popup && event.data === 'browser-request-popup-closed') {
