  const fullscreenAvailable = typeof fullscreenStage.requestFullscreen === 'function' && document.fullscreenEnabled !== false;
  badge('fullscreen', fullscreenAvailable);
  $('fullscreen-start').disabled = !fullscreenAvailable;
  $('fullscreen-start').addEventListener('click', () => request('fullscreen', () => fullscreenStage.requestFullscreen(), 'Vollbild aktiv. Esc beendet den Modus.'));
  $('fullscreen-exit').addEventListener('click', () => request('fullscreen', () => document.exitFullscreen(), 'Vollbild beendet.'));
  document.addEventListener('fullscreenchange', () => {
    $('fullscreen-start').disabled = !fullscreenAvailable || !!document.fullscreenElement;
    if (!document.fullscreenElement) report('fullscreen', 'Zurück zur normalen Ansicht.');
  });

