  const pointerAvailable = typeof pointerStage.requestPointerLock === 'function';
  badge('pointer', pointerAvailable);
  $('pointer-start').disabled = !pointerAvailable;
  $('pointer-start').addEventListener('click', () => {
    report('pointer', 'Mauszugriff angefragt. Falls er freigegeben wird: Esc beendet ihn.', 'pending');
    try {
      const result = pointerStage.requestPointerLock();
