  document.addEventListener('pointerlockchange', () => {
    const locked = document.pointerLockElement === pointerStage;
    pointerStage.dataset.locked = String(locked);
    $('pointer-label').textContent = locked ? 'Maus eingefangen. Esc zum Beenden.' : 'Deine Maus ist frei.';
