    bluetooth: {available: typeof navigator.bluetooth?.requestDevice === 'function', name: 'Bluetooth', open: () => navigator.bluetooth.requestDevice({acceptAllDevices: true})},
    usb: {available: typeof navigator.usb?.requestDevice === 'function', name: 'USB', open: () => navigator.usb.requestDevice({filters: []})},
    serial: {available: typeof navigator.serial?.requestPort === 'function', name: 'Serieller Anschluss', open: () => navigator.serial.requestPort()},
    hid: {available: typeof navigator.hid?.requestDevice === 'function', name: 'HID', open: () => navigator.hid.requestDevice({filters: []})}
  };
