    if (document.hidden && (stream || mediaPending)) {
      releaseMedia();
      report('media', 'Gerätezugriff beendet, weil die Seite nicht mehr sichtbar ist.');
    }
  });
  window.addEventListener('pagehide', () => { disposed = true; suspend(); closePopup(); });
  window.addEventListener('pageshow', () => { disposed = false; refreshMedia(); });
})();

files.styles.css:
:root{color-scheme:light;--ink:#183f3c;--muted:#607673;--paper:#f4f5ef;--line:#d8e0d5;--accent:#c3e5b1;--white:#fffefa;--blue:#edf3fc;font-family:Arial,Helvetica,sans-serif;font-size:15px}
*{box-sizing:border-box}
body{margin:0;background:var(--paper);color:var(--ink);line-height:1.55}
button,a{-webkit-tap-highlight-color:transparent}
a{color:inherit;text-underline-offset:3px}
button{font:inherit;font-size:.9rem;font-weight:600;background:var(--ink);color:var(--white);border:1px solid var(--ink);border-radius:7px;padding:11px 15px;cursor:pointer;transition:background .12s,color .12s}
button:hover:enabled{background:#2a5b55}
button.secondary{color:var(--ink);background:transparent;border-color:#becdc3}
button.secondary:hover:enabled{background:#e8efdf}
button.compact{font-size:.82rem;padding:8px 12px}
button:disabled{cursor:default;opacity:.45}
button:focus-visible,a:focus-visible{outline:3px solid #547cc9;outline-offset:4px}
.topbar{height:76px;max-width:1200px;margin:auto;padding:0 34px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);gap:16px}
.brand{display:flex;gap:12px;align-items:center;font-size:.95rem;font-weight:bold;text-decoration:none}
.brand-mark{display:grid;place-items:center;width:30px;height:30px;border-radius:8px;background:var(--ink);color:var(--accent);font-size:16px}
.header-label{font-size:.8rem;color:var(--muted)}
main{max-width:1060px;padding:0 28px;margin:auto}
.hero{padding:62px 0 38px;max-width:750px}
.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:.72rem;font-weight:bold;color:#56715c;margin:0 0 16px}
h1{font-family:Georgia,'Times New Roman',serif;font-weight:normal;letter-spacing:-.045em;font-size:clamp(2.8rem,6vw,4.6rem);line-height:1.08;margin:0 0 22px}
.intro{max-width:600px;color:var(--muted);font-size:1.06rem;margin:0 0 22px}
.environment{display:inline-flex;align-items:center;gap:9px;font-size:.79rem;background:#e6eddc;border:1px solid #d4dfc9;border-radius:30px;padding:8px 13px}
.live-dot{width:7px;height:7px;background:#60865b;border-radius:50%;flex-shrink:0}
.hero-note{font-size:.82rem;color:var(--muted);max-width:600px;margin:13px 0 0}
.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.card{background:var(--white);border:1px solid var(--line);border-radius:14px;padding:25px;min-width:0}
.card-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:15px}
.number{font-size:.75rem;letter-spacing:.08em;color:var(--muted)}
.badge{font-size:.68rem;border-radius:4px;padding:4px 7px;background:#f0f2eb;color:var(--muted)}
.badge[data-available="false"]{background:#f7eee4;color:#8a643d}
.badge[data-available="true"]{background:#e9f1df;color:#4b7149}
h2{font-size:1.25rem;letter-spacing:-.025em;line-height:1.3;margin:0 0 12px}
.card>p:not(.result){font-size:.9rem;color:var(--muted);margin:0 0 20px;min-height:63px}
.controls{display:flex;gap:9px;flex-wrap:wrap;margin:18px 0 0}
.result{background:#f2f4ed;border-left:3px solid #b4c4a6;color:#536852;padding:11px 12px;border-radius:0 5px 5px 0;font-size:.8rem;margin:18px 0 0;overflow-wrap:anywhere}
.result[data-state="pending"]{background:#eef3fb;border-color:#86a5db;color:#38567a}
.result[data-state="success"]{background:#eaf3e3;border-color:#88ad72;color:#3e6740}
.result[data-state="error"]{background:#f8eee6;border-color:#cfa883;color:#8b5633}
.camera-preview{height:185px;background:#e7eee8;border:1px solid #d8e3d9;border-radius:8px;margin:22px 0 12px;overflow:hidden;position:relative}
.camera-preview video{width:100%;height:100%;object-fit:contain;background:#163c37}
#camera-placeholder{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center;font-size:.78rem;color:var(--muted);padding:20px}
.preview-mark{width:35px;height:25px;border:2px solid #95a99b;border-radius:5px;position:relative}
.preview-mark:after{content:"";position:absolute;right:-12px;top:4px;width:8px;height:13px;border:2px solid #95a99b;border-radius:2px}
.media-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:.78rem;color:var(--muted)}
.window-illustration{height:217px;position:relative;max-width:360px;margin:18px auto 0}
.window-back,.window-front{position:absolute;border:1px solid #b9c9bb;border-radius:8px;background:#e6ecdf;width:78%;height:145px;left:0;top:17px}
.window-front{background:#fffefa;left:18%;top:49px;box-shadow:0 10px 22px #2343340d}
.window-bar{height:30px;background:#edf0e5;border-bottom:1px solid #d8e0d5;border-radius:8px 8px 0 0;display:flex;align-items:center;gap:5px;padding:10px}
.window-bar i{width:6px;height:6px;background:#a5b69d;border-radius:50%}
.window-content{display:flex;height:110px;align-items:center;justify-content:center;font-family:Georgia,serif;font-size:1.35rem}
.fullscreen-stage,.pointer-stage{height:155px;position:relative;border-radius:8px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;text-align:center;padding:24px;background:#eaf0df;color:#355541}
.fullscreen-stage strong,.pointer-stage strong{font-family:Georgia,serif;font-weight:normal;font-size:1.3rem}
.stage-corners{width:45px;height:27px;border:1px dashed #809b72}
.fullscreen-exit{display:none}
.fullscreen-stage:fullscreen{width:100%;height:100%;border-radius:0;font-size:1.4rem}
.fullscreen-stage:fullscreen strong{font-size:2.4rem}
.fullscreen-stage:fullscreen .fullscreen-exit{display:inline-block}
.pointer-stage{background:var(--blue);color:#425a77}
.pointer-stage[data-locked="true"]{background:#dce9fc}
#pointer-position{font-size:.74rem;color:#5d7798}
.crosshair{width:20px;height:20px;position:relative}
.crosshair:before,.crosshair:after{content:"";position:absolute;background:#7997be}
.crosshair:before{height:1px;width:20px;top:10px;left:0}
.crosshair:after{height:20px;width:1px;left:10px;top:0}
kbd{font:inherit;font-size:.8em;border:1px solid #cfdbd0;background:#f3f5ef;border-radius:4px;padding:1px 5px}
.device-list{border-top:1px solid var(--line);margin-top:18px}
.device-row{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:13px 0;border-bottom:1px solid var(--line)}
.device-row strong{display:block;font-size:.9rem}
.device-row span{display:block;font-size:.74rem;color:var(--muted);margin-top:2px}
.permission-block{border-top:1px solid var(--line);padding-top:17px;margin-top:17px}
.permission-block>strong{display:block;font-size:.9rem;margin-bottom:10px}
.permission-block .result{margin-top:12px}
.dialogs-card{grid-column:1/-1}
.dialogs-card>p:not(.result){min-height:0}
.activity{margin:35px 0 30px;border:1px solid var(--line);border-radius:12px;padding:24px;display:grid;grid-template-columns:1fr auto;align-items:center;gap:12px}
.activity .eyebrow{margin-bottom:7px}
.activity h2{margin:0;font-size:1.1rem}
#activity-log{list-style:none;padding:0;margin:10px 0 0;grid-column:1/-1;font-size:.81rem}
#activity-log li{border-top:1px solid var(--line);padding:11px 0;display:flex;align-items:baseline;gap:18px;overflow-wrap:anywhere}
#activity-log time{font-size:.72rem;color:var(--muted);flex-shrink:0;font-variant-numeric:tabular-nums}
#activity-log .empty-log{color:var(--muted)}
footer{border-top:1px solid var(--line);padding:22px 0 35px;font-size:.74rem;color:var(--muted)}
footer p{margin:0 0 7px}footer a{display:inline-block;margin-top:4px}
[hidden]{display:none!important}
@media(max-width:650px){.topbar{padding:0 20px;height:65px}.header-label{display:none}main{padding:0 18px}.hero{padding-top:38px}.cards{grid-template-columns:1fr}.card{padding:21px}.card>p:not(.result){min-height:0}.dialogs-card{grid-column:auto}.activity{padding:20px}.activity button{font-size:.75rem}.controls button{flex-grow:1}h1{font-size:3rem}}
@media(prefers-reduced-motion:reduce){button{transition:none}}

