let child = null;
let protectPage = false;
const status = document.getElementById('status');
function report(id, text) { document.getElementById(id).textContent = text; }
function useDialog(action) {
  try { action(); } catch (error) { report('dialog-status', 'Dieser Browserhost unterstützt den Dialog nicht: ' + error.message); }
}
document.getElementById('dialog-alert').addEventListener('click', function () {
  useDialog(function () { alert('Diese Meldung gehört zu dieser Webseite.'); report('dialog-status', 'Meldung geschlossen; der Code läuft weiter.'); });
});
document.getElementById('dialog-confirm').addEventListener('click', function () {
  useDialog(function () { const accepted = confirm('Möchtest du fortfahren?'); report('dialog-status', accepted ? 'Rückgabewert: true' : 'Rückgabewert: false'); });
});
document.getElementById('dialog-prompt').addEventListener('click', function () {
  useDialog(function () { const value = prompt('Wie soll die Notiz heißen?', 'Meine Notiz'); report('dialog-status', value === null ? 'Abgebrochen: null' : 'Text: „' + value + '“'); });
});
document.getElementById('leave-guard').addEventListener('click', function () {
  protectPage = !protectPage; this.textContent = protectPage ? 'Schutz ausschalten' : 'Schutz einschalten'; report('leave-status', protectPage ? 'Schutz ist an. Versuche Reload oder Schließen.' : 'Schutz ist aus.');
});
window.addEventListener('beforeunload', function (event) { if (protectPage) { event.preventDefault(); event.returnValue = ''; } });
window.addEventListener('pageshow', function () { report('lifecycle-status', 'pageshow · ' + document.visibilityState); });
document.addEventListener('visibilitychange', function () { report('lifecycle-status', 'visibilitychange · ' + document.visibilityState); });
function useChild(id, action) {
  if (!child || child.closed) { report(id, 'Bitte zuerst ein Zusatzfenster öffnen.'); return; }
  try { action(child); } catch (error) { report(id, error.name + ': ' + error.message); }
}
function measure() {
  useChild('geometry-status', function (win) {
    report('geometry-status', 'Position: ' + win.screenX + ' / ' + win.screenY + ' · äußere Größe: ' + win.outerWidth + ' × ' + win.outerHeight);
  });
}
document.getElementById('open').addEventListener('click', function () {
  child = window.open('../window-popup/index.html', 'vorschau', 'popup,width=420,height=320,left=90,top=90');
  status.textContent = child ? 'Das Zusatzfenster ist geöffnet.' : 'Der Host hat die Fensteranfrage abgelehnt.';
});
document.getElementById('focus').addEventListener('click', function () {
  if (child && !child.closed) child.focus();
});
document.getElementById('close').addEventListener('click', function () {
  if (!child || child.closed) { status.textContent = 'Kein geöffnetes Zusatzfenster vorhanden.'; return; }
  child.close();
  status.textContent = 'Schließen angefordert · closed unmittelbar danach: ' + child.closed;
});
document.getElementById('check').addEventListener('click', function () {
  status.textContent = !child ? 'Noch kein Fenster geöffnet.' : child.closed ? 'Das Zusatzfenster ist geschlossen.' : 'Das Zusatzfenster ist noch geöffnet.';
});
document.getElementById('tab').addEventListener('click', function () {
  window.open('../window-popup/index.html', '_blank');
});
document.getElementById('move').addEventListener('click', function () { useChild('geometry-status', function (win) { win.moveBy(25, 15); measure(); }); });
document.getElementById('position').addEventListener('click', function () { useChild('geometry-status', function (win) { win.moveTo(80, 80); measure(); }); });
document.getElementById('grow').addEventListener('click', function () { useChild('geometry-status', function (win) { win.resizeBy(40, 25); measure(); }); });
document.getElementById('size').addEventListener('click', function () { useChild('geometry-status', function (win) { win.resizeTo(520, 440); measure(); }); });
document.getElementById('measure').addEventListener('click', measure);
document.getElementById('write-dom').addEventListener('click', function () {
  useChild('dom-status', function (win) {
    const value = document.getElementById('remote-text').value;
    const target = win.document.getElementById('remote-value');
    if (!target) { report('dom-status', 'Das Zusatzfenster lädt noch.'); return; }
    target.textContent = value; target.style.color = '#395d82'; report('dom-status', 'Text im anderen Dokument geändert.');
  });
});
document.getElementById('read-dom').addEventListener('click', function () {
  useChild('dom-status', function (win) {
    const note = win.document.getElementById('note'); report('dom-status', note ? 'Notiz: ' + note.value : 'Das Zusatzfenster lädt noch.');
  });
});
document.getElementById('append-dom').addEventListener('click', function () {
  useChild('dom-status', function (win) {
    const doc = win.document; const parent = doc.getElementById('extra');
    if (!parent) { report('dom-status', 'Das Zusatzfenster lädt noch.'); return; }
    const line = doc.createElement('p'); line.textContent = 'Im Hauptfenster erstellt.'; parent.appendChild(line); report('dom-status', 'Ein neuer Absatz wurde ergänzt.');
  });
});
window.addEventListener('message', function (event) {
  if (event.source !== child || event.origin !== location.origin) return;
  if (event.data.type === 'ready') report('navigation-status', 'Zusatzfenster bereit: ' + event.data.url);
  if (event.data.type === 'reply') report('message-status', 'Antwort: ' + event.data.text + ' · Herkunft: ' + event.origin);
});
document.getElementById('send').addEventListener('click', function () {
  useChild('message-status', function (win) { report('message-status', 'Nachricht gesendet, Antwort folgt.'); win.postMessage({ type: 'greeting', text: document.getElementById('remote-text').value }, location.origin); });
});
document.getElementById('wrong-origin').addEventListener('click', function () {
  useChild('message-status', function (win) { report('message-status', 'Falsche Herkunft: Diese Nachricht muss verworfen werden.'); win.postMessage({ type: 'greeting', text: 'Darf nicht ankommen' }, 'https://wrong.invalid'); });
});
document.getElementById('navigate').addEventListener('click', function () { useChild('navigation-status', function (win) { win.location.href = '../window-popup/index.html?variante=2'; report('navigation-status', 'Variante 2 lädt.'); }); });
document.getElementById('replace').addEventListener('click', function () { useChild('navigation-status', function (win) { win.location.replace('../window-popup/index.html'); report('navigation-status', 'Erstes Dokument lädt per replace.'); }); });
document.getElementById('reload').addEventListener('click', function () { useChild('navigation-status', function (win) { win.location.reload(); report('navigation-status', 'Zusatzfenster lädt erneut.'); }); });
function fullscreen(node) {
  if (typeof node.requestFullscreen !== 'function') { report('fullscreen-status', 'Vollbild wird hier nicht unterstützt.'); return; }
  node.requestFullscreen().catch(function (error) { report('fullscreen-status', error.name + ': ' + error.message); });
}
document.getElementById('fullscreen').addEventListener('click', function () { fullscreen(document.getElementById('fullscreen-panel')); });
document.getElementById('fullscreen-page').addEventListener('click', function () { fullscreen(document.documentElement); });
document.getElementById('exit-fullscreen').addEventListener('click', function () { if (document.fullscreenElement) document.exitFullscreen(); });
document.addEventListener('fullscreenchange', function () { report('fullscreen-status', document.fullscreenElement ? 'Vollbild aktiv: ' + (document.fullscreenElement.id || document.fullscreenElement.tagName) : 'Vollbild ist aus.'); });

files.styles.css:
* { box-sizing: border-box; }
body { margin: 0; background: #edf1f5; color: #24364a; font: 16px/1.6 Arial, sans-serif; }
main { max-width: 860px; margin: 0 auto; padding: 40px 24px; }
h1 { font-size: 38px; line-height: 1.2; margin: 8px 0 18px; } h2 { margin: 0 0 10px; font-size: 23px; }
.eyebrow { color: #546b83; font-size: 12px; letter-spacing: 2px; text-transform: uppercase; }
section { margin: 24px 0; padding: 24px; border: 1px solid #ccd7e2; border-radius: 8px; background: white; }
.actions { display: flex; flex-wrap: wrap; gap: 8px; }
button { padding: 10px 14px; border: 1px solid #395d82; border-radius: 4px; background: #395d82; color: white; cursor: pointer; }
button:hover { background: #294663; } button:active { background: #1c334b; }
input { display: block; width: 100%; padding: 10px; border: 1px solid #b1c1d1; margin-top: 8px; font: inherit; }
input + .actions { margin-top: 12px; }
#fullscreen-panel:fullscreen { background: #e8f0fa; overflow: auto; padding: 32px; }
#fullscreen-panel:fullscreen h2 { font-size: 36px; }
button + button { margin-left: 4px; }
pre { overflow: auto; padding: 14px; font: 13px/1.5 monospace; background: #edf1f5; white-space: pre-wrap; }
a { color: #395d82; }

