window.addEventListener('message', function (event) {
  if (!opener || event.source !== opener || event.origin !== location.origin || event.data.type !== 'greeting') return;
  document.getElementById('message').textContent = 'Empfangen: ' + event.data.text;
  event.source.postMessage({ type: 'reply', text: 'Hallo zurück! ' + event.data.text }, event.origin);
});
